import { openModal } from './dialog-service.js';
import AiToolDialog from '@/components/ai-tool-dialog/index.vue';
import { AI_TOOL_TYPES, isValidAiToolType } from '@/types/ai-tools.js';

/**
 * 显示 AI 工具弹窗
 * @param {string} type - AI 工具类型，必须是 AI_TOOL_TYPES 中的有效值
 * @param {Object} options - 弹窗选项配置
 * @param {Object} [options.data={}] - 传递给弹窗的数据
 * @param {Function} [options.onConfirm] - 确认回调函数，第一个参数是 close 函数，第二个参数是结果对象
 * @param {Function} [options.onCancel] - 取消回调函数，第一个参数是 close 函数，第二个参数是结果对象
 * @param {boolean} [options.maskClosable=true] - 是否允许点击遮罩关闭
 * @returns {Object} 包含关闭弹窗函数的对象
 * 
 * @example
 * // 显示图像增强弹窗
 * showAiToolDialog('enhance-image', {
 *   data: { imageId: '123' },
 *   onConfirm: (close, result) => {
 *     console.log('Enhance confirmed:', result);
 *     // 执行业务逻辑后手动关闭弹窗
 *     close();
 *   },
 *   onCancel: (close, result) => {
 *     console.log('Operation cancelled:', result);
 *     close();
 *   }
 * });
 */
export function showAiToolDialog(type, options = {}) {
    // 验证弹窗类型
    if (!isValidAiToolType(type)) {
        console.error(`Invalid AI tool type: ${type}. Valid types are:`, Object.values(AI_TOOL_TYPES));
        return { close: () => {} };
    }

    const {
        data = {},
        onConfirm = null,
        onCancel = null,
        maskClosable = true,
        ...otherOptions
    } = options;

    // 构建传递给弹窗组件的 props
    const dialogProps = {
        type,
        data,
        onConfirm,
        onCancel,
        maskClosable,
        ...otherOptions
    };

    // 使用基础的 openModal 方法打开弹窗
    openModal(AiToolDialog, dialogProps);
}

/**
 * 显示图像增强弹窗
 * @param {Object} options - 弹窗选项
 * @returns {Object} 弹窗控制对象
 */
export function showEnhanceImageDialog(options = {}) {
    showAiToolDialog(AI_TOOL_TYPES.ENHANCE_IMAGE, options);
}

