import { t } from '../../language/index.js';
import { 
    showEnhanceImageDialog,
    showEditImageDialog,
    showConvertVideoDialog,
    showUpscaleImageDialog,
    showDownloadImageDialog,
    showChangeStyleDialog,
    showAddSoundtrackDialog,
    showFrameFillerDialog,
    showUpscaleVideoDialog,
    showDownloadVideoDialog
} from '@/utils/dialogMethod/ai-tool-service.js';
import { IMAGE_OPERATIONS, VIDEO_OPERATIONS } from '@/types/media-tool';
import { downloadImage, downloadVideo } from '@/utils/util.js';

/**
 * 通用的媒体操作处理器
 * @param {Object} action - 操作对象 { type: string, data: any }
 * @param {Object} mediaData - 媒体数据
 * @param {Object} options - 额外选项
 */
export function handleMediaAction(action, mediaData, options = {}) {
    const dialogData = { ...action, ...mediaData };
    const dialogOptions = {
        data: dialogData,
        onConfirm: (close, result) => {
            // 执行确认回调
            if (options.onConfirm) {
                options.onConfirm(dialogData.type, result);
            }
            close();
        },
        onCancel: (close, result) => {
            // 执行取消回调
            if (options.onCancel) {
                options.onCancel(dialogData.type, result);
            }
            close();
        }
    };
    
    // 根据 action.type 判断打开不同的弹窗或执行操作
    switch (dialogData.type) {
        // === 图片操作 ===
        case IMAGE_OPERATIONS.DOWNLOAD:
            handleImageDownload(dialogData, options);
            break;
            
        case IMAGE_OPERATIONS.ENHANCE:
            showEnhanceImageDialog(dialogOptions);
            break;
            
        case IMAGE_OPERATIONS.EDIT:
            showEditImageDialog(dialogOptions);
            break;
            
        case IMAGE_OPERATIONS.TO_VIDEO:
            showConvertVideoDialog(dialogOptions);
            break;
            
        case IMAGE_OPERATIONS.ENLARGE:
            showUpscaleImageDialog(dialogOptions);
            break;
            
        case 'viewImage':
            // handleViewMedia(mediaData, t, 'image');
            break;
            
        // === 视频操作 ===
        case VIDEO_OPERATIONS.DOWNLOAD:
            handleVideoDownload(dialogData, options);
            break;
            
        case VIDEO_OPERATIONS.UPSCALE:
            showUpscaleVideoDialog(dialogOptions);
            break;
            
        case VIDEO_OPERATIONS.SOUNDTRACK:
            showAddSoundtrackDialog(dialogOptions);
            break;
            
        case VIDEO_OPERATIONS.FRAME_FILLING:
            showFrameFillerDialog(dialogOptions);
            break;
            
        case VIDEO_OPERATIONS.VIDEO_STYLE:
            showChangeStyleDialog(dialogOptions);
            break;
        case 'viewVideo':
            // showDownloadVideoDialog(dialogOptions)
            break;
        default:
            console.warn('Unknown action type:', dialogData.type);
    }
}

/**
 * 处理图片下载操作
 * @param {Object} dialogData - 对话框数据
 * @param {Object} options - 额外选项
 */
function handleImageDownload(dialogData, options) {
    const { isloading = false } = dialogData;
    
    const dialogOptions = {
        data: dialogData,
        isloading,
        onConfirm: async (close, result) => {
            try {
                // 开始下载时设置 loading 状态
                const dialogInstance = result?.dialogInstance;
                if (dialogInstance && dialogInstance.setLoading) {
                    dialogInstance.setLoading(true);
                }
                
                // 执行下载
                const downloadResult = await downloadImage(dialogData.url);
                
                // 下载成功，执行确认回调并关闭弹窗
                if (options.onConfirm) {
                    options.onConfirm(dialogData.type, downloadResult);
                }
                close();
                
            } catch (error) {
                console.error('图片下载失败:', error);
                ElMessage.error('图片下载失败: ' + error.message);
                
                // 下载失败时停止 loading 但不关闭弹窗
                const dialogInstance = result?.dialogInstance;
                if (dialogInstance && dialogInstance.setLoading) {
                    dialogInstance.setLoading(false);
                }
            }
        },
        onCancel: (close, result) => {
            // 取消时直接关闭弹窗
            if (options.onCancel) {
                options.onCancel(dialogData.type, result);
            }
            close();
        }
    };
    
    showDownloadImageDialog(dialogOptions);
}

