/**
 * 处理查看媒体操作
 * @param {Object} mediaData - 媒体数据
 * @param {string} mediaType - 媒体类型 'image' | 'video'
 */
function handleViewMedia(mediaData, mediaType) {
    if (!mediaData?.url) {
        const warningKey = mediaType === 'image' ? 'noImageToView' : 'noVideoToView';
        return;
    }
    
    // 在新窗口中打开媒体文件
    window.open(mediaData.url, '_blank');
} 