<template>
    <div class="image-result-panel">
        <!-- 标题和描述 -->
        <div class="image-result-panel__header">
            <div class="title">{{ computedTitle }}</div>
            <div v-if="computedDescription && resultState === 'loading'" class="description">{{ computedDescription }}</div>
        </div>

        <!-- 图片展示区域 -->
        <div class="image-result-panel__content">
            <!-- 成功状态且有图片时显示图片 -->
            <template v-if="resultState === 'success' && imageUrl">
                <div ref="imageContainerRef" class="image-container">
                    <div :style="{width: `${clientWidth}px`, height: pxToRem('300px'), borderRadius: pxToRem('8px'), overflow: 'hidden'}">
                        <l-img :src="imageUrl" :w="`${clientWidth}px`" h="300px" fit="cover" :alt="'Generated Image'"
                            :previewList="[imageUrl]" class="generated-image" />
                    </div>
                </div>
                <div class="seed-info">
                    <div class="seed-info-item">
                        <div v-if="seedInfo" class="seed-label">{{ t('seed') }}:</div>
                        <div class="seed-value">{{ seedInfo }}</div>
                    </div>
                    <div class="seed-info-item favorite-item" @click="toggleFavorite">
                        <l-img :src="favoriteIcon" w="22px" h="22px" fit="contain" />
                        <div class="seed-value">{{ favoriteText }}</div>
                    </div>
                </div>
            </template>

            <!-- 其他状态（empty、loading）显示占位符 -->
            <template v-else>
                <empty-placeholder type="image" :operation-type="operationType" :button-configs="buttonConfigs"
                    :loading="resultState === 'loading'" />
            </template>
        </div>

        <!-- 操作按钮区域 -->
        <div v-if="resultState === 'success' && imageUrl" class="image-result-panel__actions">
            <action-button-group :operation-type="operationType" @action="handleAction"
                :button-configs="buttonConfigs" />
        </div>
    </div>
</template>

<script setup>
import { ref, computed, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import EmptyPlaceholder from './empty-placeholder.vue';
import ActionButtonGroup from './action-button-group.vue';
import { IMAGE_OPERATION_TYPES } from '@/types/media-tool';
import { getElementClientWidth, debounce } from '@/utils/util.js';
import { ApiGeneration } from '@/api/api-generation.ts';
import { pxToRem } from '@/utils/px-to-rem';

// Props定义
const props = defineProps({
    // 自定义标题
    title: {
        type: String,
        default: ''
    },
    
    // 自定义描述
    description: {
        type: String,
        default: ''
    },
    
    // 媒体数据
    mediaData: {
        type: Object,
        default: () => ({})
    },
    
    // 操作类型
    operationType: {
        type: String,
        default: 'image',
        validator: (value) => IMAGE_OPERATION_TYPES.includes(value)
    },
    
    // 组件状态：'empty' | 'loading' | 'success'
    resultState: {
        type: String,
        default: 'empty',
        validator: (value) => ['empty', 'loading', 'success'].includes(value)
    },
    // 预估时间
    estimatedTime: {
        type: Number,
        default: 0
    },
    // 按钮配置数组
    buttonConfigs: {
        type: Array,
        default: () => []
    }
});

// Events定义
const emit = defineEmits(['action']);

// 国际化
const { t } = useI18n();

// 响应式数据
const isFavorited = ref(false);
const imageContainerRef = ref(null);

// 计算属性：标题
const computedTitle = computed(() => {
    return props.title || t('generatedImage');
});

// 计算属性：描述
const computedDescription = computed(() => {
    return props.description || '';
});

const clientWidth = computed(() => {
    const width = getElementClientWidth(imageContainerRef.value);
    return width ? width : 0;
});

// 计算属性：图片URL
const imageUrl = computed(() => {
    return props.mediaData?.url || props.mediaData?.src || '';
});

// 计算属性：种子信息
const seedInfo = computed(() => {
    return props.mediaData?.seed || '';
});

// 计算属性：收藏图标
const favoriteIcon = computed(() => {
    return isFavorited.value ? '/static/images/hearted_icon.png' : '/static/images/heart_icon.png';
});

// 计算属性：收藏文本
const favoriteText = computed(() => {
    return isFavorited.value ? t('favorited') : t('addToFavorites');
});

// 计算属性：媒体ID
const mediaId = computed(() => {
    return props.mediaData?.media_id
});

watch(() => props.resultState, (newVal) => {
    if (newVal == 'loading') {
        isFavorited.value = false;
    }
}, { deep: true });


// 同步收藏状态到服务器
const syncFavoriteToServer = debounce(async (targetState, mediaId) => {
    try {
        const response = await ApiGeneration.toggleFavorite(mediaId);
        // 根据服务器返回确认状态
        isFavorited.value = response.data.is_favorited;
    } catch (error) {
        // 如果接口失败，回滚到目标状态
        isFavorited.value = targetState;
    }
}, 300);

// 立即执行的点击处理函数
const toggleFavorite = () => {
    // 立即切换UI状态，用户马上看到变化
    isFavorited.value = !isFavorited.value;
    
    // 调用防抖的接口同步函数
    syncFavoriteToServer(isFavorited.value, mediaId.value);
};

// 处理操作事件
const handleAction = (actionData) => {
    // 发送操作事件到父组件
    // 父组件应该使用 @/utils/util.js 中的下载方法处理下载操作
    // 示例：
    // import { downloadImage } from '@/utils/util.js';
    // case 'download': downloadImage(mediaData.url); break;
    emit('action', actionData);
};
</script>

