<template>
    <BaseModal :zIndex="zIndex" :onClose="onClose">
        <div class="ai-tool-dialog" :style="themeStyles">
            <!-- 图标区域 -->
            <div class="icon-container">
                <div class="icon-background">
                    <l-img 
                        :src="currentConfig.icon" 
                        w="24px" 
                        h="24px" 
                        class="tool-icon"
                    />
                </div>
            </div>

            <!-- 文本内容区域 -->
            <div class="content-container">
                <h2 class="dialog-title">{{ currentConfig.titleKey }}</h2>
                <p class="dialog-description">{{ currentConfig.descriptionKey }}</p>
            </div>

            <!-- 按钮区域 -->
            <div class="button-container">
                <!-- 取消按钮 -->
                <button 
                    class="cancel-button" 
                    @click="clickCancel"
                    type="button"
                >
                    {{ t('cancel') }}
                </button>

                <!-- 主要操作按钮 -->
                <el-button
                    class="confirm-button"
                    :class="{ 'outline-style': currentConfig.buttonStyle === 'outline' }"
                    @click="clickConfirm"
                    :disabled="internalLoading"
                    :loading="internalLoading"
                >
                    {{ currentConfig.buttonTextKey }}
                </el-button>
            </div>
        </div>
    </BaseModal>
</template>

<script setup>
import { computed, ref } from 'vue';
import { t } from '@/language';
import BaseModal from '@/components/dialog/open-dialog.vue';
import LImg from '@/components/l-img.vue';
import { getAiToolConfig, isValidAiToolType } from '@/types/ai-tools.js';

const props = defineProps({
    type: {
        type: String,
        required: true,
        validator: (value) => isValidAiToolType(value)
    },
    data: {
        type: Object,
        default: () => ({})
    },
    isloading:{
        type: Boolean,
        default: false
    },
    onClose: {
        type: Function,
        required: true
    },
    onConfirm: {
        type: Function,
        default: null
    },
    onCancel: {
        type: Function,
        default: null
    },
    zIndex: {
        type: Number,
        default: 3000
    }
});

// 内部 loading 状态管理
const internalLoading = ref(props.isloading);

// 提供给外部调用的 setLoading 方法
const setLoading = (loading) => {
    internalLoading.value = loading;
};

// 创建包含方法的实例对象，用于传递给回调
const dialogInstance = {
    setLoading
};

// 获取当前弹窗配置
const currentConfig = computed(() => {
    return getAiToolConfig(props.type);
});

// 计算主题样式
const themeStyles = computed(() => {
    const config = currentConfig.value;
    return {
        '--theme-color': config.themeColor || '#1D4ED8',
        '--theme-bg': config.backgroundColor || '#EFF6FF',
        '--icon-bg': config.iconBackgroundColor || '#EFF6FF',
        '--icon-border': config.iconBorder || 'none'
    };
});

// 确认按钮点击事件
const clickConfirm = () => {
    const result = {
        type: props.type,
        data: props.data,
        dialogInstance // 传递实例给回调函数
    };
    
    // 触发自定义确认事件（dialog-service 会自动注入 close 函数作为第一个参数）
    if (props.onConfirm) {
        props.onConfirm(result);
    } else {
        // 如果没有自定义回调，直接关闭弹窗
        props.onClose();
    }
};

// 取消按钮点击事件
const clickCancel = () => {
    const result = {
        type: props.type,
        dialogInstance
    };
    
    // 触发自定义取消事件（dialog-service 会自动注入 close 函数作为第一个参数）
    if (props.onCancel) {
        props.onCancel(result);
    } else {
        // 如果没有自定义回调，直接关闭弹窗
        props.onClose();
    }
};
</script>

