<template>
    <div class="empty-placeholder">
        <!-- 占位符内容区域 -->
        <div class="empty-placeholder__content">
            <div class="placeholder-area" :class="{ 'loading-state': loading }">
                <!-- loading状态下显示loading图标，否则显示正常占位符图标 -->
                <l-img 
                    :src="loading ? loadingIcon : placeholderIcon" 
                    w="56px" 
                    h="56px" 
                    :alt="loading ? loadingText : placeholderText"
                    :class="{ 'loading-icon': loading }"
                />

                <!-- 占位符文字 -->
                <p class="placeholder-text">{{ loading ? loadingText : placeholderText }}</p>
            </div>
        </div>
    </div>
</template>

<script setup>
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';

// Props定义
const props = defineProps({
    // 媒体类型：'image' | 'video'
    type: {
        type: String,
        required: true,
        validator: (value) => ['image', 'video'].includes(value)
    },
    
    // 操作类型
    operationType: {
        type: String,
        default: ''
    },
    // 是否为加载状态
    loading: {
        type: Boolean,
        default: false
    }
});

// Events定义
const emit = defineEmits(['action']);

// 国际化
const { t } = useI18n();

// 计算属性：占位符图标
const placeholderIcon = computed(() => {
    return props.type === 'image' 
        ? '/static/images/image_placeholder_icon.png'
        : '/static/images/video_placeholder_icon.png';
});

// 计算属性：loading图标
const loadingIcon = computed(() => {
    return props.type === 'image' 
        ? '/static/images/image_loading_icon.png'
        : '/static/images/video_loading_icon.png';
});

// 计算属性：占位符文字
const placeholderText = computed(() => {
    return props.type === 'image' 
        ? t('imageWillAppearHere')
        : t('videoWillAppearHere');
});

// 计算属性：loading文字
const loadingText = computed(() => {
    return props.type === 'image' 
        ? t('pictureGenerating')
        : t('videoGenerating');
});

// 计算属性：空状态按钮配置（全部透明）
const emptyActionConfig = computed(() => {
    const baseConfig = {
        visible: true,
        transparent: true // 标记为透明状态
    };

    if (props.type === 'image') {
        return {
            download: baseConfig,
            enhance: baseConfig,
            to_video: baseConfig
        };
    } else {
        return {
            download: baseConfig,
            addAudio: baseConfig
        };
    }
});

// 处理操作事件
const handleAction = (actionData) => {
    emit('action', actionData);
};
</script>

