            }

            // loading状态的特殊样式
            &.loading-state {
                .loading-icon {
                    animation: pulse 2s ease-in-out infinite;
                }

                .placeholder-text {
                    animation: fadeInOut 2s ease-in-out infinite;
                }
            }
        }
    }
    
    &__actions {
        width: 100%;
    }
}

// loading动画定义
@keyframes pulse {
    0%, 100% {
        opacity: 0.6;
        transform: scale(1);
    }
    50% {
        opacity: 1;
        transform: scale(1.05);
    }
}

@keyframes fadeInOut {
    0%, 100% {
        opacity: 0.6;
    }
    50% {
        opacity: 1;
    }
}

// 响应式断点
@media (max-width: 768px) {
    .empty-placeholder {
        &__content {
