<template>
    <div class="media-generate-result">
        <!-- 图片结果面板 -->
        <image-result-panel v-if="resultMediaType === MEDIA_TYPES.IMAGE" :title="computedTitle"
            :description="computedDescription" :estimated-time="estimatedTime" :media-data="computedMediaData"
            :operation-type="currentOperationType" :result-state="resultState" :button-configs="computedButtonConfigs"
            @action="handleAction" />

        <!-- 视频结果面板 -->
        <video-result-panel v-else-if="resultMediaType === MEDIA_TYPES.VIDEO" :title="computedTitle"
            :description="computedDescription" :estimated-time="estimatedTime" :media-data="computedMediaData"
            :operation-type="currentOperationType" :result-state="resultState" :button-configs="computedButtonConfigs"
            @action="handleAction" />
    </div>
</template>

<script setup>
import { computed } from 'vue';
import { useI18n } from 'vue-i18n';
import ImageResultPanel from './components/image-result-panel.vue';
import VideoResultPanel from './components/video-result-panel.vue';
import { ALL_OPERATION_TYPES, MEDIA_TYPES, IMAGE_OPERATIONS, VIDEO_OPERATIONS } from '@/types/media-tool';
import { pxToRem } from '@/utils/px-to-rem';

// Props定义
const props = defineProps({
    // 媒体类型：'image' | 'video'
    mediaType: {
        type: String,
        required: true,
        validator: (value) => ['image', 'video'].includes(value)
    },
    
    // 操作类型：使用常量定义的所有操作类型
    operationType: {
        type: String,
        default: '',
    },
    
    // 组件状态：'empty' | 'loading' | 'success' | 'error'
    resultState: {
        type: String,
        default: 'empty',
        validator: (value) => ['empty', 'loading', 'success', 'error'].includes(value)
    },
    
    // 媒体数据
    mediaData: {
        type: Object,
        default: () => ({})
    },
    
    // 预估时间（用于视频生成）
    estimatedTime: {
        type: Number,
        default: 0
    },
    
    // 错误信息
    errorMessage: {
        type: String,
        default: ''
    },
});

// Events定义
const emit = defineEmits(['action']);

// 国际化
const { t } = useI18n();

// 判断操作结果的媒体类型（区分操作类型和结果类型）
const getResultMediaType = (operationType, mediaType) => {
    // toVideo 操作虽然属于图片功能，但结果是视频
    if (operationType === 'to_video') {
        return 'video';
    }
    
    // 其他情况使用原始媒体类型
    return mediaType;
};

// 按钮配置数组，根据operationType返回对应的按钮配置
const getButtonConfigs = (operationType) => {
    const configs = {
        // 图片生成结果
        [IMAGE_OPERATIONS.GENERATE]: [
            {
                key: IMAGE_OPERATIONS.DOWNLOAD,
                icon: '/static/images/download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            },
            {
                key: IMAGE_OPERATIONS.ENHANCE,
                icon: '/static/images/enhance_icon.png',
                text: t('enhance'),
                backgroundColor: '#EFF6FF',
                borderColor: '#DBEAFE',
                color: "#1D4ED8"
            },
            {
                key: IMAGE_OPERATIONS.EDIT,
                icon: '/static/images/edit_icon.png',
                text: t('edit'),
                backgroundColor: '#EEF2FF',
                borderColor: '#E0E7FF',
                color: "#4338CA"
            },
            {
                key: IMAGE_OPERATIONS.TO_VIDEO,
                icon: '/static/images/video_icon.png',
                text: t('toVideo'),
                backgroundColor: '#FAF5FF',
                borderColor: '#F3E8FF',
                color: "#7E22CE"
            },
            {
                key: IMAGE_OPERATIONS.ENLARGE,
                icon: '/static/images/upscale_icon.png',
                text: t('upscale'),
                backgroundColor: '#F0FDFA',
                borderColor: '#CCFBF1',
                color: "#0F766E"
            }
        ],
        
        // 转视频结果
        [IMAGE_OPERATIONS.TO_VIDEO]: [
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/video_download_icon.png',
                text: t('download'),
                backgroundColor: '#F3F4F6',
                borderColor: '#E5E7EB',
                color: "#374151",
                height: pxToRem('72px'),
                fontSize: pxToRem('16px')
            },
            {
                key: VIDEO_OPERATIONS.SOUNDTRACK,
                icon: '/static/images/audio_icon.png',
                text: t('addAudioToVideo'),
                backgroundColor: '#EFF6FF',
                borderColor: '#BFDBFE',
                color: "#2563EB",
                height: pxToRem('72px'),
                fontSize: pxToRem('16px'),
                hasDesc: true,
            }
        ],

        // 视频生成结果
        [VIDEO_OPERATIONS.GENERATE]: [
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/video_download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            },
            {
                key: VIDEO_OPERATIONS.UPSCALE,
                icon: '/static/images/resolution_icon.png',
                text: t('upscale'),
                backgroundColor: '#F0FDFA',
                borderColor: '#CCFBF1',
                color: "#0F766E"
            },
            {
                key: VIDEO_OPERATIONS.SOUNDTRACK,
                icon: '/static/images/ai-tools/add-soundtrack.png',
                text: t('soundtrack'),
                backgroundColor: '#EEF2FF',
                borderColor: '#E0E7FF',
                color: "#4338CA"
            },
            {
                key: VIDEO_OPERATIONS.FRAME_FILLING,
                icon: '/static/images/ai-tools/frame-filler.png',
                text: t('frameFilling'),
                backgroundColor: '#FAF5FF',
                borderColor: '#F3E8FF',
                color: "#7E22CE"
            },
            
            {
                key: VIDEO_OPERATIONS.VIDEO_STYLE,
                icon: '/static/images/ai-tools/change-style.png',
                text: t('style'),
                backgroundColor: '#EFF6FF',
                borderColor: '#DBEAFE',
                color: "#1D4ED8"
            }
        ],
        
        // 增强结果
        [IMAGE_OPERATIONS.ENHANCE]: [
            {
                key: 'viewImage',
                icon: '/static/images/view_icon.png',
                text: t('viewImage'),
            },
            {
                key: IMAGE_OPERATIONS.DOWNLOAD,
                icon: '/static/images/download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ],
        
        // 放大结果
        [IMAGE_OPERATIONS.ENLARGE]: [
            {
                key: 'viewImage',
                icon: '/static/images/view_icon.png',
                text: t('viewImage'),
            },
            {
                key: IMAGE_OPERATIONS.DOWNLOAD,
                icon: '/static/images/download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ],
        
        // 编辑结果
        [IMAGE_OPERATIONS.EDIT]: [
            {
                key: 'viewImage',
                icon: '/static/images/view_icon.png',
                text: t('viewImage'),
            },
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ],

        // 配乐结果
        [VIDEO_OPERATIONS.SOUNDTRACK]: [
            {
                key: 'viewVideo',
                icon: '/static/images/view_icon.png',
                text: t('viewVideo')
            },
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/video_download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ],
        
        // 补帧结果
        [VIDEO_OPERATIONS.FRAME_FILLING]: [
            {
                key: 'viewVideo',
                icon: '/static/images/view_icon.png',
                text: t('viewVideo')
            },
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/video_download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ],
        
        // 提升分辨率结果
        [VIDEO_OPERATIONS.UPSCALE]: [
            {
                key: 'viewVideo',
                icon: '/static/images/view_icon.png',
                text: t('viewVideo')
            },
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/video_download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ],
        
        // 风格转换结果
        [VIDEO_OPERATIONS.VIDEO_STYLE]: [
            {
                key: 'viewVideo',
                icon: '/static/images/view_icon.png',
                text: t('viewVideo')
            },
            {
                key: VIDEO_OPERATIONS.DOWNLOAD,
                icon: '/static/images/video_download_icon.png',
                text: t('download'),
                backgroundColor: '#FFFFFF',
                borderColor: '#E5E7EB',
                color: "#374151"
            }
        ]
    };
    
    return configs[operationType] || [];
};

// 计算属性：当前使用的操作类型
const currentOperationType = computed(() => {
    return props.operationType || props.mediaType;
});

// 计算属性：结果的媒体类型（用于选择显示面板）
const resultMediaType = computed(() => {
    return getResultMediaType(currentOperationType.value, props.mediaType);
});

// 计算属性：根据操作类型生成标题
const computedTitle = computed(() => {
    const titleMap = {
        // 图片操作标题
        image: t('generatedImage'),
        enhance: t('textToImage'),
        enlarge: t('imageEnlargement'),
        edit: t('imageEdit'),
        to_video: t('convertToVideo'),
        
        // 视频操作标题
        video: t('generatedVideo'),
        soundtrack: t('soundtrack'),
        frameFilling: t('videoFrameFilling'),
        increaseVideoResolution: t('increaseVideoResolution'),
        changeVideoStyle: t('changeVideoStyle')
    };
    
    return titleMap[currentOperationType.value] || titleMap[props.mediaType];
});

// 将秒数转换为分钟的工具函数
const convertSecondsToMinutes = (seconds) => {
    if (seconds < 60) {
        return '1';
    }
    
    const minutes = seconds / 60;
    const floorMinutes = Math.floor(minutes);
    const ceilMinutes = Math.ceil(minutes);
    
    // 如果是整数，直接返回
    if (floorMinutes === ceilMinutes) {
        return `${floorMinutes}`;
    }
    
    // 如果不是整数，返回区间
    return `${floorMinutes}-${ceilMinutes}`;
};

// 计算属性：根据操作类型生成描述
const computedDescription = computed(() => {
    // 如果是loading状态且有预估时间，显示时间提示
    if (props.resultState === 'loading' && props.estimatedTime > 0) {
        const timeInMinutes = convertSecondsToMinutes(props.estimatedTime);
        return t('resultTime', { time: timeInMinutes });
    }
    
    const descriptionMap = {
        // 图片操作描述
        [IMAGE_OPERATIONS.GENERATE]: props.estimatedTime ? t('imageGenerateDescription', { count: props.estimatedTime }) : '',
        [IMAGE_OPERATIONS.ENHANCE]: '',
        [IMAGE_OPERATIONS.ENLARGE]: '',
        [IMAGE_OPERATIONS.EDIT]: t('imageEditDescription'),
        [IMAGE_OPERATIONS.TO_VIDEO]: t('videoWillAppearHere'),
        
        // 视频操作描述
        [VIDEO_OPERATIONS.GENERATE]: t('videoWillAppearHere'),
        [VIDEO_OPERATIONS.SOUNDTRACK]: t('soundtrackDescription'),
        [VIDEO_OPERATIONS.FRAME_FILLING]: t('frameFillingDescription'),
        [VIDEO_OPERATIONS.UPSCALE]: t('increaseVideoResolutionDescription'),
        [VIDEO_OPERATIONS.VIDEO_STYLE]: t('changeVideoStyleDescription')
    };
    
    return descriptionMap[currentOperationType.value];
});

// 计算属性：按钮配置（只在success状态显示）
const computedButtonConfigs = computed(() => {
    // 只在success状态显示按钮，其他状态返回空数组
    if (props.resultState !== 'success') {
        return [];
    }
    
    console.log('currentOperationType.value', getButtonConfigs(currentOperationType.value));
    return getButtonConfigs(currentOperationType.value);
});

// 计算属性：根据状态确定传递给子组件的媒体数据
const computedMediaData = computed(() => {
    return props.resultState === 'success' ? props.mediaData : {};
});

// 处理操作事件
const handleAction = (action) => {
    emit('action', action);
}; 
</script>

<style lang="scss" scoped>
.media-generate-result {
    width: 100%;
    max-width: 100%;
    background: var(--bg-secondary);
    border-radius: 10px;
    box-sizing: border-box;
    padding: 24px;
}
</style>