/**
 * 获取指定类型的配置信息
 * @param {string} type - AI 工具类型
 * @returns {Object} 配置对象
 */
export function getAiToolConfig(type) {
    return AI_TOOL_CONFIGS[type] || {};
}

/**
 * 检查是否为有效的 AI 工具类型
 * @param {string} type - AI 工具类型
 * @returns {boolean} 是否有效
 */
export function isValidAiToolType(type) {
    return Object.values(AI_TOOL_TYPES).includes(type);
} 