<template>
    <div class="video-result-panel">
        <!-- 标题和描述 -->
        <div class="video-result-panel__header">
            <div class="title">{{ computedTitle }}</div>
            <div v-if="resultState === 'loading'" class="description">{{ $t('videoWillAppearHere') }}</div>
            <div v-if="resultState === 'loading' && estimatedTime" class="estimated-time">{{ computedDescription }}</div>
        </div>

        <!-- 视频播放区域 -->
        <div class="video-result-panel__content">
            <!-- 成功状态且有视频时显示视频播放器 -->
            <template v-if="resultState === 'success' && videoUrl">
                <div class="video-container">
                    <l-video ref="videoRef" :src="videoUrl" :poster="posterUrl" custom-class="video-player"
                        @loadedmetadata="handleVideoLoaded" :isShowVoice="true" @timeupdate="handleTimeUpdate" @ended="handleVideoEnded">
                    </l-video>

                </div>
                <div class="seed-info">
                    <div class="seed-info-item">
                        <div v-if="seedInfo" class="seed-label">{{ t('seed') }}:</div>
                        <div class="seed-value">{{ seedInfo }}</div>
                    </div>
                    <div class="seed-info-item favorite-item" @click="toggleFavorite">
                        <l-img :src="favoriteIcon" w="22px" h="22px" fit="contain" />
                        <div class="seed-value">{{ favoriteText }}</div>
                    </div>
                </div>
            </template>

            <!-- 其他状态（empty、loading）显示占位符 -->
            <template v-else>
                <empty-placeholder type="video" :operation-type="operationType" :loading="resultState === 'loading'" />
            </template>
        </div>

        <!-- 操作按钮区域 -->
        <div v-if="resultState === 'success' && videoUrl" class="video-result-panel__actions">
            <action-button-group :operation-type="operationType" :button-configs="buttonConfigs"
                @action="handleAction" />
        </div>
    </div>
</template>

<script setup>
import { ref, computed, onMounted, onUnmounted, watch } from 'vue';
import { useI18n } from 'vue-i18n';
import ActionButtonGroup from './action-button-group.vue';
import EmptyPlaceholder from './empty-placeholder.vue';
import LImg from '@/components/l-img.vue';
import { VIDEO_OPERATION_TYPES, VIDEO_OPERATIONS } from '@/types/media-tool';
import LVideo from '@/components/l-video.vue';
import { ApiGeneration } from '@/api/api-generation.ts';
import { debounce } from '@/utils/util.js';

// Props定义
const props = defineProps({
    // 自定义标题
    title: {
        type: String,
        default: ''
    },
    
    // 自定义描述
    description: {
        type: String,
        default: ''
    },
    
    // 预估时间
    estimatedTime: {
        type: Number,
        default: 0
    },
    
    // 媒体数据
    mediaData: {
        type: Object,
        default: () => ({})
    },
    
    // 操作类型
    operationType: {
        type: String,
        default: ''
    },
    
    // 组件状态：'empty' | 'loading' | 'success'
    resultState: {
        type: String,
        default: 'empty',
        validator: (value) => ['empty', 'loading', 'success'].includes(value)
    },
    
    // 按钮配置数组
    buttonConfigs: {
        type: Array,
        default: () => []
    }
});

// Events定义
const emit = defineEmits(['action']);

// 国际化
const { t } = useI18n();

// 响应式变量
const videoRef = ref(null);
const isPlaying = ref(false);
const isMuted = ref(false);
const currentTime = ref(0);
const duration = ref(0);
const isFavorited = ref(false);

// 计算属性：标题
const computedTitle = computed(() => {
    return props.title || t('convertToVideo');
});

// 计算属性：描述
const computedDescription = computed(() => {
    return props.description || t('videoWillAppearHere');
});

// 计算属性：视频URL
const videoUrl = computed(() => {
    return props.mediaData?.url || props.mediaData?.src || '';
});

// 计算属性：海报URL
const posterUrl = computed(() => {
    return props.mediaData?.poster || '';
});

// 计算属性：种子信息
const seedInfo = computed(() => {
    return props.mediaData?.seed || '';
});

// 计算属性：收藏图标
const favoriteIcon = computed(() => {
    return isFavorited.value ? '/static/images/hearted_icon.png' : '/static/images/heart_icon.png';
});

// 计算属性：收藏文本
const favoriteText = computed(() => {
    return isFavorited.value ? t('favorited') : t('addToFavorites');
});

// 计算属性：媒体ID
const mediaId = computed(() => {
    return props.mediaData?.media_id;
});

// 播放/暂停切换
const togglePlay = () => {
    if (!videoRef.value) return;
    
    if (isPlaying.value) {
        videoRef.value.pause();
    } else {
        videoRef.value.play();
    }
    isPlaying.value = !isPlaying.value;
};

// 静音切换
const toggleMute = () => {
    if (!videoRef.value) return;
    
    videoRef.value.muted = !videoRef.value.muted;
    isMuted.value = videoRef.value.muted;
};

// 全屏切换
const toggleFullscreen = () => {
    if (!videoRef.value) return;
    
    if (document.fullscreenElement) {
        document.exitFullscreen();
    } else {
        videoRef.value.requestFullscreen();
    }
};

// 格式化时间显示
const formatTime = (seconds) => {
    const minutes = Math.floor(seconds / 60);
    const remainingSeconds = Math.floor(seconds % 60);
    return `${minutes}:${remainingSeconds.toString().padStart(2, '0')}`;
};

// 视频加载完成事件
const handleVideoLoaded = () => {
    if (videoRef.value) {
        duration.value = videoRef.value.duration || 0;
    }
};

// 时间更新事件
const handleTimeUpdate = () => {
    if (videoRef.value) {
        currentTime.value = videoRef.value.currentTime || 0;
    }
};

// 视频播放结束事件
const handleVideoEnded = () => {
    isPlaying.value = false;
};

// 同步收藏状态到服务器
const syncFavoriteToServer = debounce(async (targetState, mediaId) => {
    try {
        const response = await ApiGeneration.toggleFavorite(mediaId);
        // 根据服务器返回确认状态
        isFavorited.value = response.data.is_favorited;
    } catch (error) {
        // 如果接口失败，回滚到目标状态
        isFavorited.value = targetState;
    }
}, 300);

// 立即执行的点击处理函数
const toggleFavorite = () => {
    // 立即切换UI状态，用户马上看到变化
    isFavorited.value = !isFavorited.value;
    
    // 调用防抖的接口同步函数
    syncFavoriteToServer(isFavorited.value, mediaId.value);
};

// 处理操作事件
const handleAction = (actionData) => {
    // 发送操作事件到父组件
    // 父组件应该使用 @/utils/util.js 中的下载方法处理下载操作
    // 示例：
    // import { downloadVideo } from '@/utils/util.js';
    // case 'download': downloadVideo(mediaData.url); break;
    emit('action', actionData);
};

// 监听结果状态变化
watch(() => props.resultState, (newVal) => {
    if (newVal == 'loading') {
        isFavorited.value = false;
    }
}, { deep: true });

// 生命周期钩子
onMounted(() => {
    // 初始化视频状态
    if (videoRef.value) {
        isMuted.value = videoRef.value.muted;
    }
});

onUnmounted(() => {
    // 清理
    if (videoRef.value) {
        videoRef.value.pause();
    }
});
</script>

