                        <div class="view-label-text">{{ button.text }}</div>
                        <l-img :src="'/static/images/view_icon.png'" w="18px" h="18px" fit="contain" />
                    </div>
                    <div v-else style="display: flex; flex: 1; justify-content: flex-end;">
