                        {{ button.text }}</div>
                </div>
            </div>
        </div>
    </div>
</template>

<script setup>
import { computed } from 'vue'; 
import { useI18n } from 'vue-i18n';
import LImg from '@/components/l-img.vue';
import { ALL_OPERATION_TYPES, IMAGE_OPERATIONS } from '@/types/media-tool';
import { pxToRem } from '@/utils/px-to-rem';

// Props定义
const props = defineProps({
    // 操作类型：使用常量定义的所有操作类型
    operationType: {
        type: String,
        validator: (value) => ALL_OPERATION_TYPES.includes(value)
    },

    // 按钮配置（优先级高于内部配置）
    buttonConfigs: {
        type: Array,
        default: () => []
    },

    // 按钮配置
    config: {
        type: Object,
        default: () => ({})
    }
});

// Events定义
const emit = defineEmits(['action']);

// 国际化
const { t } = useI18n();

// 按钮配置数组
const buttonConfigs = computed(() => {
    return props.buttonConfigs?.length ? props.buttonConfigs : [];
});

// 默认按钮配置
const defaultConfig = computed(() => {
    const config = {};
    buttonConfigs.value.forEach(button => {
        config[button.key] = { visible: true, transparent: false };
    });
    return config;
});

// 合并配置
const mergedConfig = computed(() => {
    return { ...defaultConfig.value, ...props.config };
});

// 计算属性：可见的按钮列表
const visibleButtons = computed(() => {
    return buttonConfigs.value
        .filter(button => mergedConfig.value[button.key]?.visible !== false)
        .map(button => ({
            ...button,
        }));
});
// 处理按钮点击事件
const handleButtonClick = (buttonKey) => {
    emit('action', {
        type: buttonKey,
        timestamp: Date.now()
    });
};
</script>

